class Solution {
  public int maxPathScore(int[][] grid, int k) {
    int m = grid.length, n = grid[0].length;
    k = Math.min(k, m + n - 1); // a path never pays more than one per cell
    final int NEG = -1;
    int[][] dp =
        new int[n][k + 1]; // dp[j][c]: best score at the current row/column with cost exactly c
    for (int[] row : dp) Arrays.fill(row, NEG);
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        int v = grid[i][j], cost = v == 0 ? 0 : 1;
        int[] cell = dp[j];
        if (i == 0 && j == 0) {
          cell[0] = 0;
          continue;
        }
        for (int c = k; c >= 0; c--) {
          int best = NEG;
          if (c >= cost) {
            if (i > 0)
              best =
                  Math.max(best, cell[c - cost]); // from above (dp[j] still holds the previous row)
            if (j > 0) best = Math.max(best, dp[j - 1][c - cost]);
          }
          cell[c] = best == NEG ? NEG : best + v;
        }
      }
    }
    int ans = NEG;
    for (int c = 0; c <= k; c++) ans = Math.max(ans, dp[n - 1][c]);
    return ans;
  }
}
